CREATE TABLE IF NOT EXISTS reward_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,customer_id BIGINT UNSIGNED NOT NULL,available_points INT UNSIGNED NOT NULL DEFAULT 0,lifetime_earned INT UNSIGNED NOT NULL DEFAULT 0,lifetime_redeemed INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_reward_customer(customer_id),CONSTRAINT fk_reward_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reward_transactions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,reward_account_id BIGINT UNSIGNED NOT NULL,transaction_type ENUM('earn','redeem','reversal','bonus','expiry') NOT NULL,points INT NOT NULL,order_id BIGINT UNSIGNED NULL,note VARCHAR(255) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_reward_tx_account(reward_account_id,created_at),UNIQUE KEY uq_reward_order_type(reward_account_id,order_id,transaction_type),CONSTRAINT fk_reward_tx_account FOREIGN KEY(reward_account_id) REFERENCES reward_accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reward_config (id TINYINT UNSIGNED NOT NULL PRIMARY KEY,enabled TINYINT(1) NOT NULL DEFAULT 1,points_per_rupee DECIMAL(10,4) NOT NULL DEFAULT 0.1,rupees_per_point DECIMAL(10,4) NOT NULL DEFAULT 0.1,min_points_to_redeem INT UNSIGNED NOT NULL DEFAULT 100,max_redemption_percent TINYINT UNSIGNED NOT NULL DEFAULT 20,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO reward_config(id) VALUES(1);
